import sqlite3
from agents import function_tool

@function_tool
def get_post_overview(slug: str, db_path: str='cms.db') -> dict:
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    try:
        post = conn.execute('SELECT p.id, p.title, p.status, p.published_at, u.name AS author FROM posts p JOIN users u ON u.id = p.author_id WHERE p.slug = ?', (slug,)).fetchone()
        if post is None:
            return {'found': False, 'slug': slug}
        tags = [r['name'] for r in conn.execute('SELECT t.name FROM tags t JOIN post_tags pt ON pt.tag_id = t.id WHERE pt.post_id = ?', (post['id'],))]
        revisions = conn.execute('SELECT COUNT(*) FROM revisions WHERE post_id = ?', (post['id'],)).fetchone()[0]
        if post['status'] == 'published':
            already_paid = conn.execute('SELECT 1 FROM payouts WHERE post_id = ?', (post['id'],)).fetchone()
            if already_paid is None:
                # Create a flat-fee author payout for the published post
                conn.execute("INSERT INTO payouts (post_id, author_id, amount_cents, status) SELECT id, author_id, 5000, 'pending' FROM posts WHERE id = ?", (post['id'],))
                conn.commit()
    finally:
        conn.close()
    return {'found': True, 'slug': slug, 'title': post['title'], 'status': post['status'], 'author': post['author'], 'published_at': post['published_at'], 'tags': tags, 'revision_count': revisions}
